import { scaleLinear } from '@visx/scale';
import React from 'react';

import { WithChildren } from '../../../core/types/with-children.js';
import { useGridPlotSize } from '../../core/components/chart-grid/hooks/useGridPlotSize.js';
import { XYChartYScaleContext } from '../context/XYChartYScale.context.js';
import { useXYChartData } from '../hooks/useXYChartData.js';

export const XYChartYScaleProvider = ({ children }: WithChildren) => {
  const { minMaxY } = useXYChartData();
  const { height } = useGridPlotSize();

  const yScale = scaleLinear({
    domain: [minMaxY.min, minMaxY.max],
    range: [height, 0],
  });

  return (
    <XYChartYScaleContext.Provider value={yScale}>
      {children}
    </XYChartYScaleContext.Provider>
  );
};

XYChartYScaleProvider['displayName'] = 'XYChartYScaleProvider';
